   567				data->err = err;
   568	
   569				return err;
   570			} else {
   571				/* On success, the almighty scheduler might already have
   572				 * run the destroy cb on the buffer. In that case, buf
   573				 * and its metadata are dangling pointers.
   574				 */
   575				buf = NULL;
   576				data = NULL;
   577			}
