   905		if (!lechan) {
   906			LOG_DBG("no channel conn %p", conn);
   907			bt_tx_irq_raise(conn->hdev);
   908			return NULL;
   909		}
   910	
   911		/* Leave the PDU buffer in the queue until we have sent all its
   912		 * fragments.
   913		 *
   914		 * For SDUs we do the same, we keep it in the queue until all the
   915		 * segments have been sent, adding the PDU headers just-in-time.
   916		 */
   917		struct net_buf *pdu = k_fifo_peek_head(&lechan->tx_queue);
   918	
   919		/* We don't have anything to send for the current channel. We could
   920		 * however have something to send on another channel that is attached to
   921		 * the same ACL connection. Re-trigger the TX processor: it will call us
   922		 * again and this time we will select another channel to pull data from.
   923		 */
   924		if (!pdu) {
   925			bt_tx_irq_raise(conn->hdev);
   926			return NULL;
   927		}
   928	
   929		if (bt_buf_has_view(pdu)) {
   930			LOG_ERR("already have view on %p", pdu);
   931			return NULL;
   932		}
   933	
   934		if (lechan->_pdu_remaining == 0 && !chan_has_credits(lechan)) {
   935			/* We don't have credits to send a new K-frame PDU. Remove the
   936			 * channel from the ready-list, it will be added back later when
   937			 * we get more credits.
   938			 */
   939			LOG_DBG("no credits for new K-frame on %p", lechan);
   940			lower_data_ready(lechan);
   941			return NULL;
   942		}
   943	
   944		/* Add PDU header */
   945		if (lechan->_pdu_remaining == 0) {
   946			struct bt_l2cap_hdr *hdr;
   947			uint16_t pdu_len = get_pdu_len(lechan, pdu);
   948	
   949			LOG_DBG("Adding L2CAP PDU header: buf %p chan %p len %u / %u",
   950				pdu, lechan, pdu_len, pdu->len);
   951	
   952			LOG_HEXDUMP_DBG(pdu->data, pdu->len, "PDU payload");
   953	
   954			hdr = net_buf_push(pdu, sizeof(*hdr));
   955			hdr->len = sys_cpu_to_le16(pdu_len);
   956			hdr->cid = sys_cpu_to_le16(lechan->tx.cid);
   957	
   958			lechan->_pdu_remaining = pdu_len + sizeof(*hdr);
   959			chan_take_credit(lechan);
   960		}
