   962		/* Whether the data to be pulled is the last ACL fragment */
   963		bool last_frag = amount >= lechan->_pdu_remaining;
   964	
   965		/* Whether the data to be pulled is part of the last L2CAP segment. For
   966		 * static channels, this variable will always be true, even though
   967		 * static channels don't have the concept of L2CAP segments.
   968		 */
