  1062			return;
  1063		}
  1064	
  1065		LOG_DBG("processing conn %p", conn);
  1066	
  1067		if (conn->state != BT_CONN_CONNECTED) {
  1068			LOG_WRN("conn %p: not connected", conn);
  1069	
  1070			/* Call the user callbacks & destroy (final-unref) the buffers
  1071			 * we were supposed to send.
  1072			 */
  1073			buf = conn->tx_data_pull(conn, SIZE_MAX, &buf_len);
  1074			while (buf) {
  1075				destroy_and_callback(conn, buf, cb, ud);
  1076				buf = conn->tx_data_pull(conn, SIZE_MAX, &buf_len);
  1077			}
  1078	
  1079			goto exit;
  1080		}
  1081	
  1082		/* now that we are guaranteed resources, we can pull data from the upper
  1083		 * layer (L2CAP or ISO).
  1084		 */
  1085		buf = conn->tx_data_pull(conn, conn_mtu(conn), &buf_len);
  1086		if (!buf) {
  1087			/* Either there is no more data, or the buffer is already in-use
  1088			 * by a view on it. In both cases, the TX processor will be
  1089			 * triggered again, either by the view's destroy callback, or by
  1090			 * the upper layer when it has more data.
  1091			 */
  1092			LOG_DBG("no buf returned");
  1093	
  1094			goto exit;
  1095		}
  1096	
  1097		bool last_buf = conn_mtu(conn) >= buf_len;
  1098	
  1099		if (last_buf) {
  1100			/* Only pull the callback info from the last buffer.
  1101			 * We still allocate one TX context per-fragment though.
  1102			 */
  1103			conn->get_and_clear_cb(conn, buf, &cb, &ud);
  1104			LOG_DBG("pop: cb %p userdata %p", cb, ud);
  1105		}
  1106	
  1107		LOG_DBG("TX process: conn %p buf %p (%s)",
  1108			conn, buf, last_buf ? "last" : "frag");
  1109	
  1110		int err = send_buf(conn, buf, buf_len, cb, ud);
