   293	static void tx_notify_process(struct bt_conn *conn)
   294	{
   295		/* TX notify processing is done only from a single thread. */
   296		__ASSERT_NO_MSG(k_current_get() == k_work_queue_thread_get(tx_notify_workqueue_get()));
   297	
   298		LOG_DBG("conn %p", (void *)conn);
   299	
   300		while (1) {
   301			struct bt_conn_tx *tx = NULL;
   302			unsigned int key;
   303			bt_conn_tx_cb_t cb;
   304			void *user_data;
   305	
   306			key = irq_lock();
   307			if (!sys_slist_is_empty(&conn->tx_complete)) {
   308				const sys_snode_t *node = sys_slist_get_not_empty(&conn->tx_complete);
   309	
   310				tx = CONTAINER_OF(node, struct bt_conn_tx, node);
   311			}
   312			irq_unlock(key);
   313	
   314			if (!tx) {
   315				return;
   316			}
   317	
   318			LOG_DBG("tx %p cb %p user_data %p", tx, tx->cb, tx->user_data);
   319	
   320			/* Copy over the params */
   321			cb = tx->cb;
   322			user_data = tx->user_data;
   323	
   324			/* Free up TX notify since there may be user waiting */
   325			tx_free(conn->hdev, tx);
   326	
   327			/* Run the callback, at this point it should be safe to
   328			 * allocate new buffers since the TX should have been
   329			 * unblocked by tx_free.
   330			 */
   331			if (cb) {
   332				cb(conn, user_data, 0);
   333			}
   334	
   335			LOG_DBG("raise TX IRQ");
   336			bt_tx_irq_raise(conn->hdev);
   337		}
   338	}
