  1040	void bt_conn_tx_processor(struct bt_dev *hdev)
  1041	{
  1042		LOG_DBG("start");
  1043		struct bt_conn *conn;
  1044		struct net_buf *buf;
  1045		bt_conn_tx_cb_t cb = NULL;
  1046		size_t buf_len;
  1047		void *ud = NULL;
  1048	
  1049		if (!IS_ENABLED(CONFIG_BT_CONN_TX)) {
  1050			/* Mom, can we have a real compiler? */
  1051			return;
  1052		}
  1053	
  1054		if (IS_ENABLED(CONFIG_BT_TESTING) && _suspend_tx) {
  1055			return;
  1056		}
  1057	
  1058		conn = get_conn_ready(hdev);
  1059	
  1060		if (!conn) {
  1061			LOG_DBG("no connection wants to do stuff");
  1062			return;
  1063		}
  1064	
  1065		LOG_DBG("processing conn %p", conn);
  1066	
  1067		if (conn->state != BT_CONN_CONNECTED) {
  1068			LOG_WRN("conn %p: not connected", conn);
  1069	
  1070			/* Call the user callbacks & destroy (final-unref) the buffers
  1071			 * we were supposed to send.
  1072			 */
  1073			buf = conn->tx_data_pull(conn, SIZE_MAX, &buf_len);
  1074			while (buf) {
  1075				destroy_and_callback(conn, buf, cb, ud);
  1076				buf = conn->tx_data_pull(conn, SIZE_MAX, &buf_len);
  1077			}
  1078	
  1079			goto exit;
  1080		}
  1081	
  1082		/* now that we are guaranteed resources, we can pull data from the upper
  1083		 * layer (L2CAP or ISO).
  1084		 */
  1085		buf = conn->tx_data_pull(conn, conn_mtu(conn), &buf_len);
  1086		if (!buf) {
  1087			/* Either there is no more data, or the buffer is already in-use
  1088			 * by a view on it. In both cases, the TX processor will be
  1089			 * triggered again, either by the view's destroy callback, or by
  1090			 * the upper layer when it has more data.
  1091			 */
  1092			LOG_DBG("no buf returned");
  1093	
  1094			goto exit;
  1095		}
  1096	
  1097		bool last_buf = conn_mtu(conn) >= buf_len;
  1098	
  1099		if (last_buf) {
  1100			/* Only pull the callback info from the last buffer.
  1101			 * We still allocate one TX context per-fragment though.
  1102			 */
  1103			conn->get_and_clear_cb(conn, buf, &cb, &ud);
  1104			LOG_DBG("pop: cb %p userdata %p", cb, ud);
  1105		}
  1106	
  1107		LOG_DBG("TX process: conn %p buf %p (%s)",
  1108			conn, buf, last_buf ? "last" : "frag");
  1109	
  1110		int err = send_buf(conn, buf, buf_len, cb, ud);
  1111	
  1112		if (err) {
  1113			/* -EIO means `unrecoverable error`. It can be an assertion that
  1114			 *  failed or an error from the HCI driver.
  1115			 *
  1116			 * -ENOMEM means we thought we had all the resources to send the
  1117			 *  buf (ie. TX context + controller buffer) but one of them was
  1118			 *  not available. This is likely due to a failure of
  1119			 *  assumption, likely that we have been pre-empted somehow and
  1120			 *  that `tx_processor()` has been re-entered.
  1121			 *
  1122			 *  In both cases, we destroy the buffer and mark the connection
  1123			 *  as dead.
  1124			 */
  1125			LOG_ERR("Fatal error (%d). Disconnecting %p", err, conn);
  1126			destroy_and_callback(conn, buf, cb, ud);
  1127			bt_conn_disconnect(conn, BT_HCI_ERR_REMOTE_USER_TERM_CONN);
  1128	
  1129			goto exit;
  1130		}
  1131	
  1132		/* Always kick the TX work. It will self-suspend if it doesn't get
  1133		 * resources or there is nothing left to send.
  1134		 */
  1135		bt_tx_irq_raise(hdev);
  1136	
  1137	exit:
  1138		/* Give back the ref that `get_conn_ready()` gave us */
  1139		bt_conn_unref(conn);
  1140	}
