	}

	if (should_stop_tx(conn)) {
		/* Move reference off the list and into the `conn` variable. */
		__maybe_unused sys_snode_t *s = sys_slist_get(&hdev->le.conn_ready);

		__ASSERT_NO_MSG(s == node);
		(void)atomic_set(&conn->_conn_ready_lock, 0);

