	 * pointer will still be reachable. Make sure that we don't try
	 * to use the destroyed context later.
	 */
	conn_tx_destroy(conn, tx);
	k_sem_give(bt_conn_get_pkts(conn));

	/* Merge HCI driver errors */
	return -EIO;
}

