L197:     {
L198: 
L199:         HAL_PIN_Set(PAD_PA40, I2C3_SCL, PIN_PULLUP, 1);
L200:         HAL_PIN_Set(PAD_PA39, I2C3_SDA, PIN_PULLUP, 1);
L201:         rt_base_t vsys = GET_PIN(1,38);
L202:         rt_pin_mode(vsys, PIN_MODE_OUTPUT);
L203:         rt_pin_write(vsys, PIN_HIGH);
L204: 
