  pthread_mutex_lock(&g_state_lock);
  g_imu_raw_started = true;
  pthread_mutex_unlock(&g_state_lock);

  detach_ret = pthread_detach(thread);
  printf("openvela_ble_probe: IMU raw pthread detach ret=%d\n", detach_ret);
}

